def fuzzy(seq, pat, maxmm):
    out=[]
    L=len(pat)
    for i in range(len(seq)-L+1):
        mm=sum(1 for a,b in zip(seq[i:i+L],pat) if a!=b)
        if mm<=maxmm:
            out.append((i,seq[i:i+L],mm))
    return out

