seq = open('region.fasta').read()
s = ''.join(l.strip() for l in seq.split('\n')[1:] if l.strip())
n=len(s)

# seed-and-extend: seeds = all 12-mers, allow extension with mismatch tolerance via local alignment score
from collections import defaultdict
idx=defaultdict(list)
k=12
for i in range(n-k+1):
    idx[s[i:i+k]].append(i)

def extend(i,j):
    # extend left
    l=0
    while i-l-1>=0 and j-l-1>=0 and s[i-l-1]==s[j-l-1]:
        l+=1
    r=0
    while j+r<n and i+r<n and i+r<j and s[i+r]==s[j+r]:
        r+=1
    return (i-l, j-l, l+r)

pairs={}
for kmer,pos in idx.items():
    if len(pos)>1:
        for a in range(len(pos)):
            for b in range(a+1,len(pos)):
                i,j=pos[a],pos[b]
                if j-i<20: continue
                st,st2,L=extend(i,j)
                # record per (st,st2)
                key=(st,st2)
                if L>=40:
                    pairs[key]=max(pairs.get(key,0),L)

# collapse
items=sorted(pairs.items(), key=lambda kv:-kv[1])
