print("stop-codon counts per frame (expected ~46.9 for 1000 codons):")
for strand,name in [(s,'+'),(rc(s),'-')]:
    for f in range(3):
        cod=[strand[i:i+3] for i in range(f,n-2,3)]
        print("  %s frame %d: %d stops  (of %d codons)" % (name,f,sum(1 for c in cod if c in stops),len(cod)))

print()
